import { motion } from "framer-motion";
import { ArrowRight, Bus, CarTaxiFront, TrainFront } from "lucide-react";

const iconMap = {
  bus: Bus,
  train: TrainFront,
  cab: CarTaxiFront,
};

function TransportCard({ item, theme, onSelect }) {
  const Icon = iconMap[item.type] || Bus;
  const isLight = theme === "light";

  return (
    <motion.div
      whileHover={{ y: -6, scale: 1.01 }}
      className={`rounded-[28px] border p-6 transition ${
        isLight
          ? "border-neutral-900/8 bg-white/75"
          : "border-white/10 bg-white/5"
      }`}
    >
      <div className="flex items-center justify-between">
        <div className="flex h-14 w-14 items-center justify-center rounded-2xl saffron-gradient text-neutral-950">
          <Icon className="h-5 w-5" />
        </div>
        <span className={`rounded-full px-3 py-1 text-xs font-medium ${isLight ? "bg-[#FFF3E0] text-[#E65100]" : "bg-[#FF9933]/12 text-[#FFB066]"}`}>
          {item.accent}
        </span>
      </div>
      <h3 className={`mt-5 font-display text-2xl font-semibold ${isLight ? "text-neutral-900" : "text-white"}`}>
        {item.title}
      </h3>
      <p className={`mt-3 text-sm leading-7 ${isLight ? "text-neutral-600" : "text-white/60"}`}>
        {item.description}
      </p>
      <button
        type="button"
        onClick={() => onSelect(item.type)}
        className="mt-6 inline-flex items-center gap-2 rounded-full bg-[#FF9933]/12 px-4 py-2 text-sm font-semibold text-[#FF9933] transition hover:bg-[#FF9933]/16"
      >
        Explore {item.title}
        <ArrowRight className="h-4 w-4" />
      </button>
    </motion.div>
  );
}

export default TransportCard;
