import { Clock3, History, Ticket } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { transportTypes } from "../data/transports";
import { useAuth } from "../context/AuthContext";
import { useBooking } from "../context/BookingContext";
import PageShell from "../components/PageShell";
import TransportCard from "../components/TransportCard";
import { formatCurrency, formatType } from "../utils/booking";

function HomePage({ theme, onToggleTheme, pushToast }) {
  const { bookingHistory } = useBooking();
  const { isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const isLight = theme === "light";

  const handleTransportClick = (type) => {
    const target = `/${type}`;
    if (!isAuthenticated) {
      localStorage.setItem("yatri-post-login-path", target);
      pushToast({
        type: "info",
        title: "Login required",
        message: "Please login before starting a booking.",
      });
      navigate("/login", { state: { from: { pathname: target } } });
      return;
    }

    navigate(target);
  };

  return (
    <PageShell theme={theme} onToggleTheme={onToggleTheme}>
      <section className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
        <div className={`rounded-[32px] border p-7 ${isLight ? "border-neutral-900/8 bg-white/78" : "border-white/10 bg-white/5"}`}>
          <p className={`text-xs uppercase tracking-[0.3em] ${isLight ? "text-neutral-500" : "text-white/45"}`}>
            Home
          </p>
          <h1 className={`mt-4 font-display text-4xl font-semibold ${isLight ? "text-neutral-900" : "text-white"} sm:text-5xl`}>
            Multi-transport booking built to feel premium.
          </h1>
          <p className={`mt-5 max-w-2xl text-base leading-8 ${isLight ? "text-neutral-600" : "text-white/62"}`}>
            Explore bus, train, and cab options through a product-grade booking flow with mock APIs, sticky summaries, seat selection, loaders, and locally persisted booking history.
          </p>

          <div className="mt-8 grid gap-4 sm:grid-cols-3">
            {[
              { label: "Transport types", value: "3", icon: Ticket },
              { label: "Max seats", value: "6", icon: History },
              { label: "Fast mock API", value: "<1s", icon: Clock3 },
            ].map((stat) => (
              <div
                key={stat.label}
                className={`rounded-[24px] border p-4 ${isLight ? "border-neutral-900/8 bg-[#FFF9F3]" : "border-white/10 bg-black/20"}`}
              >
                <stat.icon className="h-4.5 w-4.5 text-[#FF9933]" />
                <p className={`mt-4 font-display text-2xl font-semibold ${isLight ? "text-neutral-900" : "text-white"}`}>
                  {stat.value}
                </p>
                <p className={`mt-2 text-sm ${isLight ? "text-neutral-600" : "text-white/55"}`}>{stat.label}</p>
              </div>
            ))}
          </div>
        </div>

        <div className={`rounded-[32px] border p-7 ${isLight ? "border-neutral-900/8 bg-white/78" : "border-white/10 bg-white/5"}`}>
          <p className={`text-xs uppercase tracking-[0.3em] ${isLight ? "text-neutral-500" : "text-white/45"}`}>
            Recent bookings
          </p>
          {bookingHistory.length ? (
            <div className="mt-5 overflow-hidden rounded-[24px] border border-white/10">
              <div className={`grid grid-cols-[1fr_auto_auto] gap-4 px-4 py-3 text-xs uppercase tracking-[0.2em] ${isLight ? "bg-[#FFF3E0] text-neutral-500" : "bg-white/6 text-white/40"}`}>
                <span>Route</span>
                <span>Type</span>
                <span>Total</span>
              </div>
              {bookingHistory.slice(0, 4).map((booking) => (
                <div
                  key={booking.id}
                  className={`grid grid-cols-[1fr_auto_auto] gap-4 border-t px-4 py-4 text-sm ${
                    isLight ? "border-neutral-900/8 bg-white/78 text-neutral-700" : "border-white/10 bg-black/10 text-white/72"
                  }`}
                >
                  <div>
                    <p className={`font-medium ${isLight ? "text-neutral-900" : "text-white"}`}>
                      {booking.details.from} to {booking.details.to}
                    </p>
                    <p className={isLight ? "text-neutral-500" : "text-white/45"}>{booking.id}</p>
                  </div>
                  <span>{formatType(booking.type)}</span>
                  <span>{formatCurrency(booking.totalPrice)}</span>
                </div>
              ))}
            </div>
          ) : (
            <div className={`mt-5 rounded-[24px] border border-dashed p-6 ${isLight ? "border-neutral-900/12 bg-[#FFF9F3] text-neutral-600" : "border-white/10 bg-black/20 text-white/60"}`}>
              No bookings yet. Start with a bus, train, or cab route below.
            </div>
          )}
        </div>
      </section>

      <section className="mt-8 grid gap-5 md:grid-cols-3">
        {transportTypes.map((item) => (
          <TransportCard
            key={item.type}
            item={item}
            theme={theme}
            onSelect={handleTransportClick}
          />
        ))}
      </section>
    </PageShell>
  );
}

export default HomePage;
